sys_script_fix.script:
var _page = new GlideRecord("sys_cs_adapter_configuration_page_slack");
_page.query();
while (_page.next()) {
    var clientType = _page.client_type;
	var configStr = new sn_cs_adapter.AdapterConfigGenerator().getDefaultConfig(clientType);
	var defaultConfig = JSON.parse(configStr);
	var adapter_config = new GlideRecord("sys_cs_adapter_configuration");
	adapter_config.addQuery("sys_cs_adapter_configuration_page", _page.sys_id);
	adapter_config.query();
	while (adapter_config.next()) {
		var name = adapter_config.attribute_name.trim();
		var value = adapter_config.attribute_value.trim();
		if(
		(name.equals("final_date_time_conf_msg") && value.equals("Please verify the date/time. To confirm, click OK. To change, click any field. You can also enter the date/time in the format of MM/DD/YYYY HH:mm AM/PM."))||
		(name.equals("final_date_confirm_msg") && value.equals("Please verify the date/time. To confirm, click OK. To change, click any field. You can also enter the date/time in the format of MM/DD/YYYY."))||
		(name.equals("final_time_confirm_msg") && value.equals("Please verify the date/time. To confirm, click OK. To change, click any field. You can also enter the date/time in the format of HH:mm AM/PM.")))
		{
			adapter_config.attribute_value=defaultConfig[name];
		}
		adapter_config.update();
	}
	//End Of Updating  newly introduced  messages  which customer didn't update from sys_cs_adapter_configuration_page to sys_cs_adapter_configuration

}
